css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); display: grid; grid-template-columns: repeat(3, 1fr); gap: 5%; padding: 5%; border-radius: 9%; background: color-mix(in srgb, #fff 74%, var(--accent-2)); box-shadow: inset 0 0 0 2px color-mix(in srgb, #000 12%, var(--accent-2)); }
.loader span { border-radius: 50%; background: radial-gradient(circle at 34% 28%, rgba(255, 255, 255, .95), color-mix(in srgb, #fff 52%, var(--accent))); box-shadow: inset 0 calc(var(--loader-size) * -.015) calc(var(--loader-size) * .03) rgba(15, 23, 42, .18); animation: deflate calc(var(--loader-speed) * 2.7) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * 1.5); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .9); }
.loader span:nth-child(6) { animation-delay: calc(var(--loader-speed) * 2.1); }
.loader span:nth-child(7) { animation-delay: calc(var(--loader-speed) * 1.2); }
.loader span:nth-child(8) { animation-delay: calc(var(--loader-speed) * 2.4); }
.loader span:nth-child(9) { animation-delay: calc(var(--loader-speed) * 1.8); }
@keyframes deflate { 0%, 38% { transform: scale(1); } 44% { transform: scale(1.18); } 52% { transform: scale(.68); } 60%, 100% { transform: scale(1); } }
